'use strict';
const $ = (q) => document.querySelector(q);
const $$ = (q) => [...document.querySelectorAll(q)];
const escapeHTML = (s) => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon = (name) => `<svg aria-hidden="true"><use href="#i-${name}"/></svg>`;
const KEY = 'maybe-studio-v1';
const themes = {
 retro: {word:'复古',question:'复古，是回到哪一年？',sub:'算了，先试试再说。',labels:['旧杂志的秩序','不太听话的复古','一个慢吞吞的夏天'],notes:['先从旧纸张开始','复古，也可以很大声','这一张，有点我的私心'],colors:[['#f3e7cd','#8b3d3f','#c76346'],['#ef7752','#413b65','#fae6b8'],['#d4e3cb','#315c61','#f4da7c']]},
 bauhaus: {word:'包豪斯',question:'你说的是几何，还是那股秩序感？',sub:'先让圆和方块吵一架。',labels:['秩序先行','几何不想上班','颜色先说话'],notes:['圆也有自己的立场','故意偏了一点点','红黄蓝，暂时和解'],colors:[['#f4e7cf','#252e43','#cb4937'],['#e9c446','#273d73','#f6eee0'],['#d94e3e','#efda9a','#30394f']]},
 dream: {word:'梦幻',question:'梦，是轻飘飘，还是有点奇怪？',sub:'这一轮，允许逻辑请假。',labels:['一场清醒的梦','梦里的坏天气','月亮也会走神'],notes:['重力暂时不在场','有一点荒诞也挺好','不知道，但喜欢'],colors:[['#e4d8ee','#644b87','#ec9d78'],['#a5bfd8','#453d73','#e3cf7b'],['#e8b8ba','#654b77','#c9dcac']]},
 quiet: {word:'安静',question:'安静，要留多少空白才够？',sub:'我先把声音调小一点。',labels:['空白也在说话','少一点，再少一点','留在纸上的呼吸'],notes:['这里什么也没放','小一点，也能被看见','还可以继续删'],colors:[['#f0eee4','#625c5c','#b5ad9d'],['#d8d9d3','#515b59','#eee9dc'],['#e5dcd4','#696875','#b8c3b0']]},
 green: {word:'自然',question:'自然，是一片森林，还是一阵风？',sub:'先种下三个不太一样的念头。',labels:['野生的秩序','今天去外面','一阵路过的风'],notes:['不整齐，也很生动','给绿色一点自由','轻一点，再轻一点'],colors:[['#e4e8cd','#3e6950','#d5a85c'],['#83a97b','#f5e7a7','#35504c'],['#d8dfc8','#56735d','#d8b9a0']]}
};
function freshState(){return {version:1,prompt:'帮我做一张复古风格的海报',theme:'retro',mood:'open',seed:0,iteration:0,selection:null,paletteLock:null,mode:'normal',intent:'复古',current:'三种猜测',messages:[{role:'user',text:'帮我做一张复古风格的海报',tag:'示例开场'},{role:'assistant',text:'“复古”……我先圈住这个词。\n是旧杂志，还是小时候那个夏天？',tag:'有点拿不准',question:true},{role:'assistant',text:'我先猜了三个方向。\n不保证猜对，但说不定会撞出点什么。\n\n你可以偏爱一个，也可以全都推翻。',tag:'先试试看',options:['想要更安静一点','试试包豪斯风格']}],events:[]};}
let state=freshState(),busy=false,operation=0,toastTimer,storageAvailable=true;
try {const saved=JSON.parse(localStorage.getItem(KEY));if(saved&&saved.version===1&&themes[saved.theme]&&Array.isArray(saved.messages)&&Array.isArray(saved.events)&&typeof saved.prompt==='string'&&Number.isFinite(saved.seed))state=saved;}catch{storageAvailable=false;}
function snapshot(){return {prompt:state.prompt,theme:state.theme,mood:state.mood,seed:state.seed,iteration:state.iteration,selection:state.selection,paletteLock:state.paletteLock,mode:state.mode,intent:state.intent,current:state.current};}
function event(title,detail){state.events.push({title,detail,time:new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}),snapshot:snapshot()});state.events=state.events.slice(-40);}
if(!state.events.length)event('一开始，你说“复古”','示例开场：系统暂时把“复古”拆成旧纸张、强烈排版和夏日记忆。');
function save(){state.messages=state.messages.slice(-70);try{localStorage.setItem(KEY,JSON.stringify(state));$('#save-status').textContent='已留在这台设备';}catch{storageAvailable=false;$('#save-status').textContent='暂存于本次页面';}$('#local-note').textContent=storageAvailable?'只存在这台设备 · 随时可以改主意':'浏览器无法保存 · 刷新会清空';}
function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000);}
function textLine(text,x,y,size,color,extra=''){return `<text x="${x}" y="${y}" font-size="${size}" fill="${color}" ${extra}>${escapeHTML(text)}</text>`;}
function getCustomTitle(){const match=state.prompt.match(/[“「《"]([^”」》"]{1,14})[”」》"]/);if(match)return match[1];if(/咖啡/.test(state.prompt))return '咖啡，慢一点';if(/音乐|爵士|演出/.test(state.prompt))return '把声音留住';if(/书|阅读/.test(state.prompt))return '读到一阵风';if(/电影/.test(state.prompt))return '散场以后';if(/花|春天/.test(state.prompt))return '春天会经过';return null;}
function effectivePalette(index){
 const t=themes[state.theme];
 if(Array.isArray(state.paletteLock))return [...state.paletteLock];
 let palette=[...t.colors[(index+Math.floor(state.seed/3))%3]];
 if(state.mood==='bold')palette=[...t.colors[(index+1)%3]];
 if(state.mood==='warm')palette=[index===1?'#e8a57c':'#f2e0bd',palette[1],'#bf6855'];
 return palette;
}
function posterSVG(index){
 const t=themes[state.theme];let [bg,ink,accent]=effectivePalette(index);
 const seed=state.seed%7,custom=getCustomTitle(),shift=seed*8;
 let content='';const serif='font-family="Georgia,serif"';const sans='font-family="Arial,\'PingFang SC\',sans-serif"';
 if(state.mode==='smile'&&index===1){content=`<rect width="300" height="400" fill="#f6d77d"/><circle cx="150" cy="188" r="91" fill="#f4c55c"/><ellipse cx="120" cy="171" rx="7" ry="12" fill="#684b59"/><ellipse cx="180" cy="171" rx="7" ry="12" fill="#684b59"/><path d="M107 213Q150 258 193 213" stroke="#684b59" stroke-width="6" fill="none" stroke-linecap="round"/>${textLine('先笑一下。',150,325,22,'#684b59',`${sans} text-anchor="middle"`)}${textLine('I HAVE NO IDEA. YET.',150,353,10,'#684b59',`${sans} text-anchor="middle" letter-spacing="2"`)}${textLine('MAYBE THIS IS A BEGINNING',150,38,9,'#684b59',`${sans} text-anchor="middle" letter-spacing="1.5"`)}`;
 }else if(state.theme==='quiet'){
 content=`<rect width="300" height="400" fill="${bg}"/>${textLine('THE SPACE BETWEEN',26,34,8,ink,`${sans} letter-spacing="2"`)}<path d="M26 47H274" stroke="${ink}" stroke-width=".6"/><circle cx="${index===0?220:150}" cy="${170+shift}" r="${index===1?35:55}" fill="${accent}"/>${index===2?`<path d="M40 220Q150 100 260 240" fill="none" stroke="${ink}" stroke-width="1"/>`:''}${textLine(custom||['留 白','慢 一 点','呼 吸'][index],26,index===0?275:310,index===1?24:35,ink,`${sans} font-weight="300"`)}${textLine('A little room for nothing.',26,345,12,ink,serif)}${textLine('MAYBE STUDIO / EXPLORATION',26,376,7,ink,`${sans} letter-spacing="1"`)}`;
 }else if(state.theme==='dream'){
 content=`<rect width="300" height="400" fill="${bg}"/><circle cx="${150+shift}" cy="165" r="97" fill="${accent}"/><ellipse cx="150" cy="185" rx="128" ry="34" transform="rotate(-28 150 185)" fill="none" stroke="${ink}" stroke-width="2"/><rect x="${90-shift/2}" y="134" width="100" height="152" rx="50" fill="${ink}"/><circle cx="150" cy="184" r="38" fill="${bg}"/>${textLine('SOMEWHERE',24,46,26,ink,`${serif} font-style="italic"`)}${textLine('ELSE.',24,80,35,ink,serif)}${textLine(custom||['梦，不必解释','偶尔失重','月亮走神了'][index],24,337,20,ink,sans)}${textLine('A SMALL ESCAPE FROM CERTAINTY',24,370,7,ink,`${sans} letter-spacing="1.6"`)}`;
 }else if(state.theme==='bauhaus'){
 content=`<rect width="300" height="400" fill="${bg}"/>${textLine('FORM / PLAY',22,34,10,ink,`${sans} letter-spacing="2"`)}<rect x="22" y="${66+shift/2}" width="133" height="133" fill="${ink}"/><circle cx="${190-shift/2}" cy="200" r="83" fill="${accent}"/><path d="M22 214H155V310H22Z" fill="${accent}"/><path d="M177 83H277V295H177Z" stroke="${ink}" fill="none" stroke-width="2"/>${textLine(custom||'形状有话说',22,354,29,ink,`${sans} font-weight="700"`)}${textLine('CIRCLE. SQUARE. SOMETHING ELSE.',22,380,7,ink,`${sans} letter-spacing="1.2"`)}`;
 }else if(state.theme==='green'){
 content=`<rect width="300" height="400" fill="${bg}"/>${textLine('GROW AT YOUR OWN PACE',24,33,8,ink,`${sans} letter-spacing="1.4"`)}<path d="M150 300V110" stroke="${ink}" stroke-width="3"/><ellipse cx="109" cy="170" rx="39" ry="73" transform="rotate(-42 109 170)" fill="${ink}"/><ellipse cx="188" cy="207" rx="41" ry="70" transform="rotate(40 188 207)" fill="${accent}"/><circle cx="${218-shift}" cy="91" r="29" fill="${accent}"/>${textLine(custom||['野生的念头','今天去外面','让风经过'][index],24,345,27,ink,sans)}${textLine('NOT EVERYTHING NEEDS A PLAN.',24,376,8,ink,`${sans} letter-spacing="1.1"`)}`;
 }else if(index===0){
 content=`<rect width="300" height="400" fill="${bg}"/><rect x="15" y="15" width="270" height="370" fill="none" stroke="${ink}" stroke-width=".8"/>${textLine('A NOTE FROM ANOTHER TIME',150,37,7,ink,`${sans} text-anchor="middle" letter-spacing="1.6"`)}${textLine('Yester',150,106,67,ink,`${serif} text-anchor="middle" font-style="italic"`)}${textLine('day.',150,164,67,ink,`${serif} text-anchor="middle" font-style="italic"`)}<path d="M53 302v-48a97 97 0 0 1 194 0v48Z" fill="${accent}"/><path d="M73 302v-47a77 77 0 0 1 154 0v47M94 302v-47a56 56 0 0 1 112 0v47M115 302v-47a35 35 0 0 1 70 0v47" fill="none" stroke="${bg}" stroke-width="1.6"/><circle cx="150" cy="255" r="${14+seed}" fill="${bg}"/>${textLine(custom||'昨日慢递',150,337,17,ink,`${sans} text-anchor="middle" letter-spacing="4"`)}${textLine('GOOD THINGS TAKE THE LONG WAY.',150,367,6.6,ink,`${sans} text-anchor="middle" letter-spacing="1.2"`)}`;
 }else if(index===1){
 content=`<rect width="300" height="400" fill="${bg}"/>${textLine('SOME THINGS NEVER GET OLD',21,29,7,ink,`${sans} letter-spacing="1.1"`)}<circle cx="${215-shift}" cy="268" r="104" fill="${ink}"/><circle cx="222" cy="271" r="73" fill="none" stroke="${accent}" stroke-width="1"/>${textLine('GOOD',16,112,65,ink,`${sans} font-weight="900" letter-spacing="-4"`)}${textLine('OLD',16,178,75,ink,`${sans} font-weight="900" letter-spacing="-4"`)}${textLine('DAYS.',16,245,70,accent,`${sans} font-weight="900" letter-spacing="-4"`)}<path d="m52 286 6 18 19 1-15 12 5 19-15-11-16 11 5-19-15-12 20-1Z" fill="${accent}"/>${textLine(custom||'把昨天，过得大声一点。',20,378,10,ink,sans)}`;
 }else{
 content=`<rect width="300" height="400" fill="${bg}"/>${textLine('THE ART OF DOING NOTHING',150,32,7,ink,`${sans} text-anchor="middle" letter-spacing="1.5"`)}<circle cx="${210-shift}" cy="118" r="60" fill="${accent}"/><path d="M29 260V173a71 71 0 0 1 142 0v87Z" fill="${ink}"/><path d="M124 265v-72a72 72 0 0 1 144 0v72Z" fill="${bg}" stroke="${ink}" stroke-width="2"/><path d="M29 280H268M29 292H268M29 304H268" stroke="${ink}" stroke-width="1"/>${textLine(custom||'慢慢，入夏',150,350,25,ink,`${sans} text-anchor="middle" letter-spacing="3"`)}${textLine('TAKE YOUR TIME, SUNSHINE.',150,377,7,ink,`${sans} text-anchor="middle" letter-spacing="1.3"`)}`;
 }
 return `<svg xmlns="http://www.w3.org/2000/svg" width="900" height="1200" viewBox="0 0 300 400" role="img" aria-label="${escapeHTML(custom||t.labels[index])}">${content}</svg>`;
}
function renderPosters(animate=false){const theme=themes[state.theme];$('#poster-grid').innerHTML=[0,1,2].map(i=>`<button class="poster-choice ${state.selection===i?'selected':''}" data-select="${i}" aria-label="选择方向 ${'ABC'[i]}：${escapeHTML(state.mode==='smile'&&i===1?'先笑一下':theme.labels[i])}" aria-pressed="${state.selection===i}">${state.selection===i?`<span class="selected-badge">${icon('check')}就是有点感觉</span>`:''}<div class="poster-mat"><div class="poster-art">${posterSVG(i)}</div><div class="poster-bottom"><span class="poster-caption"><span class="poster-letter">${'ABC'[i]}.</span>${escapeHTML(state.mode==='smile'&&i===1?'先笑一下，再想':theme.labels[i])}</span><span class="mini-arrow">${icon('arrow')}</span></div></div><span class="poster-note">${escapeHTML(state.mode==='smile'&&i===1?'此刻，理解暂时缺席':theme.notes[i])}</span></button>`).join('');$('#poster-grid').classList.toggle('entering',animate);}
function renderMessages(){
 $('#conversation').innerHTML=`<div class="conversation-label">允许跑题的创作对话</div>`+state.messages.map(m=>`<div class="message ${m.role==='user'?'user':'assistant'}"><div class="message-meta">${m.role==='user'?'你':'Maybe'}${m.tag?`<span class="tag">${escapeHTML(m.tag)}</span>`:''}</div>${m.question?'<span class="mini-question" aria-hidden="true">?</span>':''}<div class="message-text">${escapeHTML(m.text)}</div>${m.options?`<div class="message-options">${m.options.map(t=>`<button data-prompt="${escapeHTML(t)}">${escapeHTML(t)}</button>`).join('')}</div>`:''}</div>`).join('')+(busy?'<div class="message assistant typing"><div class="message-meta">Maybe <span class="tag">试探中</span></div><div class="message-text">等一下，让我想岔一会儿…<span class="typing-dots"><i></i><i></i><i></i></span></div></div>':'');
 $('#conversation').scrollTop=$('#conversation').scrollHeight;
}
function renderJourney(){const total=state.events.length;$('#journey-count').textContent=total;$('#rail-count').textContent=total;$('#journey-list').innerHTML=state.events.map((e,i)=>`<li class="journey-item"><small>${String(i+1).padStart(2,'0')} / ${escapeHTML(e.time)}</small><h3>${escapeHTML(e.title)}</h3><p>${escapeHTML(e.detail)}</p>${i<total-1?`<button data-restore="${i}">从这个念头重新出发</button>`:'<small>你现在在这里。下一步，随你。</small>'}</li>`).join('');}
function render(animate=false){const t=themes[state.theme];renderPosters(animate);renderMessages();renderJourney();$('#current-prompt').textContent=state.prompt;$('#brief-label').textContent=state.iteration?'现在的念头':'最初的念头';$('#question-copy').innerHTML=`${escapeHTML(state.mode==='smile'?'当我想不明白的时候…':t.question)}<small>${escapeHTML(state.mode==='smile'?'先把气氛搞好，也算一种进展？':t.sub)}</small>`;$('#guess-label').textContent=state.selection===null?`我先猜了三个方向${state.iteration?' · 第 '+(state.iteration+1)+' 次试探':''}`:'你刚刚偏爱了一个方向';$('#canvas-title').innerHTML=state.iteration?'好像，有点新想法了<span>。</span>':'先别急着想清楚<span>。</span>';$('#ribbon-path').innerHTML=`<span>${escapeHTML(state.intent.slice(0,9))}</span><span class="path-arrow">→</span><span>${escapeHTML(state.current.slice(0,10))}</span><span class="path-arrow">→</span><span class="pending">${state.selection===null?'等你偏心…':'还可以改主意'}</span>`;$('#board-footnote').textContent=state.selection===null?'不一定是答案，但可以是个开始。':'喜欢它的哪一点？说出来，或者继续凭感觉。';save();}
function addMessage(role,text,tag,options,question=false){state.messages.push({role,text,tag,options,question});}
function setBusy(value){busy=value;$('#companion-status').textContent=value?'正在认真地想岔':'正在认真地不确定';$('#artboard').setAttribute('aria-busy',String(value));$$('[data-action],#send-button,#regenerate-button,[data-select],[data-prompt]').forEach(el=>el.disabled=value);$('#input-hint').textContent=value?'念头正在转弯…':'改主意，也是一种进展';}
async function respond(work){const id=++operation;setBusy(true);renderMessages();$$('[data-prompt]').forEach(el=>el.disabled=true);await new Promise(resolve=>setTimeout(resolve,850));if(id!==operation)return;work();setBusy(false);render(true);}
function classify(text){if(/包豪斯|bauhaus|几何|红黄蓝/i.test(text))return 'bauhaus';if(/梦|超现实|奇幻|宇宙|太空|荒诞/.test(text))return 'dream';if(/安静|极简|留白|疏离|克制|简洁|少一点/.test(text))return 'quiet';if(/自然|森林|植物|绿色|春|花园/.test(text))return 'green';if(/复古|怀旧|旧|retro/i.test(text))return 'retro';return state.theme;}
async function sendPrompt(text){text=text.trim().slice(0,240);if(!text){$('#prompt-input').focus();toast('一个词也行，把念头丢进来。');return;}if(busy)return;$('#prompt-input').value='';addMessage('user',text,'新念头');showView('canvas');await respond(()=>{const keepColors=/保留配色|保持配色|配色不变/.test(text);const retained=keepColors?effectivePalette(state.selection??0):null;state.paletteLock=retained;const before=themes[state.theme].word;const next=classify(text);state.theme=next;state.prompt=text;state.mode='normal';state.selection=null;state.seed++;state.iteration++;state.mood=/大胆|大声|夸张|鲜艳|热闹/.test(text)?'bold':/温暖|暖色|温柔/.test(text)?'warm':'open';const ambiguous=/不知道|不懂|说不上|说不清|随便|高级.*便宜|既要.*又要/.test(text);const changed=next!==Object.keys(themes).find(k=>themes[k].word===before);state.current=ambiguous?'暂时没想清楚':themes[next].word;let response,tag;if(keepColors){response='好，这次把你偏爱的配色留下。\n我只挪动形状和排版，再试出几个不同的样子。';tag='留住这一点';}else if(ambiguous){response='好，那我们先不急着给它起名字。\n我还是试了三种可能——你不喜欢的部分，也是一条线索。';tag='允许模糊';}else if(changed){response=`噢，方向拐弯了。\n“${before}”先放到旁边，我把“${themes[next].word}”往前挪一点。\n\n是你改主意了，还是我刚才理解偏了？你说了算。`;tag='一个转弯';}else if(state.mood==='bold'){response='收到，“再大胆一点”。\n我把颜色和声音一起开大了。\n要是太吵，我们再把它拽回来。';tag='稍微失控';}else if(state.mood==='warm'){response='我先把“温暖”理解成更软的底色、晒过太阳的纸。\n如果你说的是另一种温暖，就继续纠正我。';tag='暂时这样理解';}else {response=`“${text.length>35?text.slice(0,35)+'…':text}”\n我先按“${themes[next].word}”的方向继续试，换了颜色和构图。\n这只是草案，你可以告诉我哪一部分想岔了。`;tag='先试试看';}addMessage('assistant',response,tag,changed?['是我改主意了','其实你刚才理解错了']:['更大胆一点','留白多一点'],ambiguous);event(changed?`从“${before}”拐向“${themes[next].word}”`:`又试了一种“${state.current}”`,text+'\n系统采用暂时理解并更新草案，仍等待你的反馈。');});}
async function selectPoster(index){if(busy)return;const label=state.mode==='smile'&&index===1?'先笑一下':themes[state.theme].labels[index];state.selection=index;state.current=label;addMessage('user',`这一张，有点感觉。${'ABC'[index]} · ${label}`,'偏爱发生了');event(`你偏爱了“${label}”`,'草案引发了一次选择；目前还不知道你喜欢的是配色、构图，还是它带来的感觉。');render();await respond(()=>{addMessage('assistant',index===2?'我就知道你可能会多看它一眼。\n但我还不想替你下结论——\n你喜欢的是颜色，还是它慢悠悠的感觉？':index===1?'噢，你选了这个有点不听话的。\n那我们就沿着它，再偏一点点？\n当然，你随时可以反悔。':'你偏爱这张。\n是排版让你停了一下，还是那种气氛？\n我们可以沿着这个感觉继续走。','捕捉到一点感觉',['保留配色，再试试','想要更安静一点','其实我改主意了']);});}
async function action(name){if(busy)return;const messages={drift:'大胆跑偏一次，看看会发生什么。',doubt:'等等，再犹豫一下。',smile:'实在想不明白，就先笑一个吧。',regenerate:'这三个都不是，全都推翻。'};addMessage('user',messages[name],'允许跑题');showView('canvas');await respond(()=>{if(name==='doubt'){addMessage('assistant','等等，我可能把“风格”理解得太像一个标签了。\n你想要的，会不会其实是一种感觉？\n\n这次先不动海报。看看它们，哪一张让你有一点反应？','暂时悬置',['安静但有一点疏离','像小时候的夏天'],true);event('我们暂时没有往前走','保留当前草案，重新讨论风格背后可能存在的感受。');}else if(name==='smile'){state.mode='smile';state.selection=null;state.current='一个意外的笑脸';state.iteration++;addMessage('assistant','说实话，这一刻我没想明白。\n但画布空着怪尴尬的，所以……\n我先递给你一个笑脸。\n\n它没解决问题。也许能让我们换个心情再来。','理解暂时缺席',['好吧，重新试试','那就再荒诞一点']);event('一个笑脸打断了创作','用刻意无关的产出暴露“有输出”和“理解了意图”之间的距离。');}else {state.mode='normal';state.paletteLock=null;state.selection=null;state.iteration++;state.seed+=name==='drift'?3:1;if(name==='drift'){const keys=Object.keys(themes);state.theme=keys[(keys.indexOf(state.theme)+1)%keys.length];state.mood='bold';state.current='意外的'+themes[state.theme].word;addMessage('assistant',`好，我故意拐错了一个弯。\n这一轮借了点“${themes[state.theme].word}”的感觉。\n\n不喜欢就算了，万一呢？`,'有意跑偏',['这个意外不错','回到复古的感觉']);event('我们故意走了一条岔路',`暂时试探“${themes[state.theme].word}”，不将它视为用户已确认的意图。`);}else {state.current='换一组猜测';addMessage('assistant','全都不要？好，完全可以。\n排除三个答案，也算知道了一点什么。\n\n我换了构图和配色，再把三个新猜测放在这里。','重新试探',['方向还是不对','试试梦幻一点']);event('三个草案被全部推翻','保留讨论记录，重新生成构图与配色变化。');}}});}
function showView(view){const journey=view==='journey';$('#canvas-view').hidden=journey;$('#journey-view').hidden=!journey;$$('.view-tabs [data-view]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.view===view)));$$('.rail [data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));}
function correction(text){if(busy)return;addMessage('user',text,'纠正记录');if(text==='其实你刚才理解错了'){addMessage('assistant','明白，我把记录改准确一点：\n这一步是“纠正系统的理解”，不能直接算成“你改变了意图”。','谢谢纠正');event('这是纠正理解，不是改变主意','用户明确指出：此前系统的理解偏离了原有意图。');}else {addMessage('assistant','好，这一次就记作“我看着草案，产生了新的想法”。\n这个转弯，属于你。','意图发生变化');event('你确认自己改变了主意','用户明确确认：新的创作方向在看到草案后形成。');}render();}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.view){showView(b.dataset.view);return;}if(b.dataset.select!==undefined){selectPoster(Number(b.dataset.select));return;}if(b.dataset.action){action(b.dataset.action);return;}if(b.dataset.prompt){if(['是我改主意了','其实你刚才理解错了'].includes(b.dataset.prompt))correction(b.dataset.prompt);else sendPrompt(b.dataset.prompt);return;}if(b.dataset.restore!==undefined){if(busy)return;const old=state.events[Number(b.dataset.restore)];if(!old)return;Object.assign(state,old.snapshot);addMessage('assistant',`好，我们回到“${old.title}”这个念头。\n后来的岔路也留着，你随时可以重新看看。`,'回到旧念头');event('从旧念头重新出发',`回到：${old.title}`);showView('canvas');render(true);toast('回到这一步了，旧轨迹仍然保留。');}});
$('#prompt-form').addEventListener('submit',e=>{e.preventDefault();sendPrompt($('#prompt-input').value);});
$('#prompt-input').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();sendPrompt(e.currentTarget.value);}});
$('#regenerate-button').addEventListener('click',()=>action('regenerate'));
$('#edit-prompt').addEventListener('click',()=>{$('#prompt-input').value=state.prompt;$('#prompt-input').focus();$('#prompt-input').select();if(innerWidth<761)$('#prompt-form').scrollIntoView({behavior:'smooth',block:'center'});});
function toggleGuide(force){const open=force===undefined?$('#guide').hidden:force;$('#guide').hidden=!open;$('#guide-button').setAttribute('aria-expanded',String(open));}
$('#guide-button').addEventListener('click',()=>toggleGuide());$('#close-guide').addEventListener('click',()=>toggleGuide(false));
$('#personality-button').addEventListener('click',()=>{if(busy)return;addMessage('assistant','嗨，我是小未。\n会猜，会跑题，也会承认没听懂。\n你不用先写出完美的需求，我们一起试。\n\n顺带一提：这个原型里的我由预设脚本扮演，海报也是矢量草案。','认识一下');renderMessages();save();});
$('#reset-button').addEventListener('click',()=>$('#reset-dialog').showModal());$('#cancel-reset').addEventListener('click',()=>$('#reset-dialog').close());
$('#confirm-reset').addEventListener('click',()=>{operation++;setBusy(false);state=freshState();event('一开始，你说“复古”','示例开场：系统暂时把“复古”拆成旧纸张、强烈排版和夏日记忆。');$('#reset-dialog').close();showView('canvas');render(true);toast('换好白纸了。我们重新乱想。');});
$('#export-button').addEventListener('click',()=>{const i=state.selection??0,blob=new Blob([posterSVG(i)],{type:'image/svg+xml;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`Maybe-${themes[state.theme].word}-${'ABC'[i]}.svg`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);toast(state.selection===null?'先带走 A 方案。选中其他海报后也可以保存。':'已带走这张海报，SVG 可以继续编辑。');});
$$('.view-tabs button').forEach((b,i,all)=>b.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();const next=all[1-i];showView(next.dataset.view);next.focus();}}));
render();
